  'yaroslavl-vyatskoe-muzey-kuhonnoy-mashinerii': '/images/venues/yaroslavl/vyatskoe-muzey-kuhonnoy-mashinerii.jpg',
  'yaroslavl-vyatskoe-muzey-russkoy-predpriimchivosti': '/images/venues/yaroslavl/vyatskoe-muzey-russkoy-predpriimchivosti.jpg',
